# Expected values generated by test/scipy/gen_integrate_bvp.py (scipy 1.18.1).
import numpy as np
from scipy.integrate import solve_bvp

def close(x, ref, rtol: float = 1e-7, atol: float = 1e-10) -> bool:
    a = np.asarray(x, float)
    r = np.asarray(ref, float)
    if a.size != r.size:
        print('size', a.size, r.size)
        return False
    ok = True
    for u, v in zip(a.flat, r.flat):
        if abs(u - v) > atol + rtol * abs(v):
            print('mismatch', u, v)
            ok = False
    return ok

def check(cond: bool, what: str):
    if not cond:
        print('TEST FAILED:', what)

def fun1(x, y):
    return np.vstack((y[1], -np.exp(y[0])))

def bc1(ya, yb):
    return np.array([ya[0], yb[0]])

def fun2(x, y, p):
    return np.vstack((y[1], -p[0] ** 2 * y[0]))

def bc2(ya, yb, p):
    return np.array([ya[0], yb[0], ya[1] - p[0]])

def fun_jac(x, y):
    df_dy = np.zeros((2, 2, x.size))
    df_dy[0, 1, :] = 1
    df_dy[1, 0, :] = -np.exp(y[0])
    return df_dy

def bc_jac(ya, yb):
    return np.array([[1.0, 0.0], [0.0, 0.0]]), np.array([[0.0, 0.0], [1.0, 0.0]])

def fun3(x, y):
    return np.vstack((y[1], 2 * y[0] * 0 + 1.0 + 0 * x))

def bc3(ya, yb):
    return np.array([ya[1], yb[0] - 1])

def test_bratu():
    x = np.linspace(0, 1, 5)
    r = solve_bvp(fun1, bc1, x, np.zeros((2, 5)))
    check(r.status == 0 and r.success and r.niter == 1 and r.x.size == 5, 'bratu status')
    check(close(r.sol(np.array([0.25, 0.5, 0.75]))[0], [0.10478414478746345, 0.140534772543497, 0.10478414478746347]), 'bratu sol')
    check(close(r.sol(np.array([0.3]), 1)[0], [0.2282651232821]), 'bratu sol deriv')
    check(abs(r.rms_residuals.max() - 0.0001053606024959714) < 1e-9, 'bratu rms')
    r = solve_bvp(fun1, bc1, x, np.zeros((2, 5)), tol=1e-10, max_nodes=20)
    check(r.status == 1 and r.niter == 2 and r.x.size == 13, 'maxnodes')
    check(r.message == 'The maximum number of mesh nodes is exceeded.', 'maxnodes message')

def test_param():
    x = np.linspace(0, 1, 5)
    y = np.zeros((2, 5))
    y[0] = np.sin(np.pi * x)
    r = solve_bvp(fun2, bc2, x, y, p=[6.0])
    check(r.status == 0 and r.niter == 3 and r.x.size == 11, 'eig status')
    check(close(r.p, [3.1416713916040617]), 'eig p')
    check(close(r.sol(np.array([0.3]))[0], [0.808973580205354]), 'eig sol')

def test_jac_singular():
    x = np.linspace(0, 1, 5)
    r = solve_bvp(fun1, bc1, x, np.zeros((2, 5)), fun_jac=fun_jac, bc_jac=bc_jac, tol=1e-6)
    check(r.status == 0 and r.niter == 4 and r.x.size == 29, 'jac status')
    check(close(r.y[0][::8], [0.0, 0.10478730969338627, 0.13654571105551022, 0.06068537865383007], 1e-6, 1e-9), 'jac y')
    S = np.array([[0.0, 0.0], [0.0, -1.0]])
    x2 = np.linspace(0, 1, 11)
    r = solve_bvp(fun3, bc3, x2, np.zeros((2, 11)), S=S)
    check(r.status == 0 and r.niter == 1 and r.x.size == 11, 'sing status')
    check(close(r.y[0][::2], [0.7499999999991444, 0.7599999999995877, 0.7899999999991727, 0.8399999999917058, 0.9099999999923281, 1.0], 1e-7, 1e-9), 'sing y')

test_bratu()
test_param()
test_jac_singular()
print('integrate bvp OK')
